CREATE INDEX "unmatched_cards_collection_bin_unemptied_idx" ON "unmatched_cards" USING btree ("collection_id","bin_number") WHERE "unmatched_cards"."bin_emptied_at" IS NULL AND "unmatched_cards"."is_deleted" = false;